contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint seed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (seed) + (10)); require(seed <= 1000000000000000000000000000000);
        require(seed == 10);
        require(address(this).balance >= seed + 10);
        c.play{value: seed}(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        c.play{value: 10}(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;
        assert(
            potAfter == 0 ||
            (balAfter == balBefore + 10 && potAfter == potBefore + 10)
        );
    }
    receive() external payable {}
}

