// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 seed) internal {
        seed = bound(seed, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        seed = 10;
        vm.assume(address(this).balance >= seed + 10);
        try c.play{value: seed}() {} catch { return; }
        uint balBefore = address(c).balance;
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        try c.play{value: 10}() {} catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(potAfter == 0 ||
            (balAfter == balBefore + 10 && potAfter == potBefore + 10));
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
